contracts/AlienListrack.sol.content:
// SPDX-License-Identifier: MIT
// AlienListrack (AL): the contract deployed on the external ledger E.
// It records Alice's leg under the TxId derived on the regulated ledger R,
// groups recorded legs into time slots and exposes each closed slot's Merkle
// root and proofs through read-only functions.
//
// Revision (JFMI version of the paper, Section 4.3):
//  1. The external-leg deadline T_E is enforced HERE, on E. The deadline and the
//     hash-lock refund time T_A are computed on R and bound into TxId, so AL
//     enforces exactly the values R registered and needs no copy of R's parameters.
//  2. Slots are genesis-anchored: slot = (t - genesisTimestamp) / slotLength.
//     A slot is closed once the current slot is greater; roots and proofs are
//     served only for closed slots.
//  3. Merkle tree with domain separation and a committed leaf count (ListrackMerkle).
//  Fixes: each TxId can be recorded once; hash-lock claims and refunds use the
//  token of that trade and are mutually exclusive in time; native-coin legs work.

pragma solidity ^0.8.24;

import {ReentrancyGuard} from "./utils/ReentrancyGuard.sol";
import {ListrackMerkle} from "./ListrackMerkle.sol";
import "hardhat/console.sol";

interface IERC20 {
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function allowance(address owner, address spender) external returns (uint256);
}

contract AlienListrack is ReentrancyGuard {

    // Alien leg transferred to Mike (plain mode) or claimed by Mike (hash-lock mode)
    event AlienSettled(bytes32 indexed _drexTxId, uint256 _alienBlock, uint256 _alienMerkleTxIndex);
    // Alien leg escrowed under the hashed secret (hash-lock mode)
    event AlienLocked(bytes32 indexed _drexTxId, uint256 _alienBlock, uint256 _alienMerkleTxIndex);
    // Alien leg returned to Alice (hash-lock mode, after T_A)
    event AlienRefunded(bytes32 indexed _drexTxId, address indexed _aliceAddress);

    struct TxStatus {
        uint256 slotNumber;       // [0] slot in which the leg was recorded
        uint256 txIndex;          // [1] leaf index inside that slot
        bool    isSettled;
        address aliceAddress;
        address mikeAddress;
        uint256 alienAmount;
        bytes32 hashedSecret;
        uint256 timeStampInserted;
        bool    isRefunded;       // true once no further transfer can happen
        address tokenContract;    // asset of this leg (address(0) = native coin)
        uint256 alienDeadline;    // T_E as a timestamp, bound into TxId
        uint256 alienRefundTime;  // T_A as a timestamp, bound into TxId
    }

    // slot number => TxIds recorded in that slot (the leaves of its Merkle tree)
    mapping (uint256 => bytes32[]) public chainConfirmedTx;

    // TxId => status of the alien leg
    mapping (bytes32 => TxStatus) public transactions;

    // slot length in seconds and the common genesis timestamp of the slot clock
    uint256 public immutable slotLength;
    uint256 public immutable genesisTimestamp;

    /// @param _slotLength        slot length in seconds
    /// @param _genesisTimestamp  start of slot 0; 0 = deployment time
    constructor(uint256 _slotLength, uint256 _genesisTimestamp) payable {
        require(_slotLength > 0, "Slot length must be positive");
        slotLength = _slotLength;
        genesisTimestamp = (_genesisTimestamp == 0) ? block.timestamp : _genesisTimestamp;
        require(genesisTimestamp <= block.timestamp, "Genesis in the future");
    }

    /// @notice Current slot of the genesis-anchored slot clock.
    function currentSlot() public view returns (uint256) {
        return (block.timestamp - genesisTimestamp) / slotLength;
    }

    /// @notice A slot is closed (its leaf set can no longer change) once the clock has moved past it.
    function isSlotClosed(uint256 _slotNumber) public view returns (bool) {
        return _slotNumber < currentSlot();
    }

    /// @notice Kept for compatibility with earlier scripts.
    function getLatestSlot() public view returns (uint256) {
        return currentSlot();
    }

    // Alice records her leg. The contract must have been approved by Alice to move
    // her tokens (ERC-20 approve), or the call must carry the native amount.
    function writeAlienLeg (
        // below are the inputs generated by the agreed transaction
        bytes32 _drexHashFields,
        address _aliceAlienAddress,
        address _mikeAlienAddress,
        address _alientokencontract, // alien contract to transfer tokens
        uint256 _alienAmount,
        bytes32 _hashedSecret,
        // below are the inputs generated by the Drex (regulated) chain
        bytes32 _drexPreviousId,
        uint256 _drexTxIndex,
        bytes32 _drexTxId,
        uint256 _alienDeadline,
        uint256 _alienRefundTime
    ) external payable nonReentrant
    {
        require(_alienAmount > 0, "Invalid Alien amount");
        require(_mikeAlienAddress != address(0), "No Mike Address");
        require(msg.sender == _aliceAlienAddress, "Only Alice can send this Transaction");

        // TxId re-derivation: the same chained hash computed by DrexListrack.setTrade
        bytes32 _fields = keccak256(abi.encodePacked(
            _drexHashFields, _aliceAlienAddress, _mikeAlienAddress, _alientokencontract, _alienAmount));
        bytes32 _position = keccak256(abi.encodePacked(
            _fields, _hashedSecret, _drexTxIndex, _alienDeadline, _alienRefundTime));
        require(keccak256(abi.encodePacked(_drexPreviousId, _position)) == _drexTxId,
            "Drex Id Hash is not equal to the inputed parameters");

        // each TxId can be recorded only once (no double use, no double escrow)
        require(transactions[_drexTxId].aliceAddress == address(0), "Transaction already recorded");

        // T_E enforced on E: a late leg is rejected before any asset moves
        require(block.timestamp <= _alienDeadline, "Alien leg deadline has passed");

        if (_alientokencontract == address(0)) {
            require(msg.value == _alienAmount, "Incorrect Alien amount sent");
        } else {
            require(msg.value == 0, "Native coin sent with a token leg");
        }

        bool success;
        if (_hashedSecret == bytes32(0)) {
            // plain mode: y goes straight to Mike
            if (_alientokencontract == address(0)) {
                (success,) = payable(_mikeAlienAddress).call{value: _alienAmount}("");
            } else {
                success = IERC20(_alientokencontract).transferFrom(msg.sender, _mikeAlienAddress, _alienAmount);
            }
        } else {
            // hash-lock mode: y is escrowed here under the hashed secret
            if (_alientokencontract == address(0)) {
                success = true; // msg.value is already held by this contract
            } else {
                success = IERC20(_alientokencontract).transferFrom(msg.sender, address(this), _alienAmount);
            }
        }
        require(success, "Alien transfer failed");

        uint256 _slot = currentSlot();
        chainConfirmedTx[_slot].push(_drexTxId);
        uint256 _index = chainConfirmedTx[_slot].length - 1;

        TxStatus storage t = transactions[_drexTxId];
        t.slotNumber        = _slot;
        t.txIndex           = _index;
        t.aliceAddress      = _aliceAlienAddress;
        t.mikeAddress       = _mikeAlienAddress;
        t.alienAmount       = _alienAmount;
        t.hashedSecret      = _hashedSecret;
        t.timeStampInserted = block.timestamp;
        t.tokenContract     = _alientokencontract;
        t.alienDeadline     = _alienDeadline;
        t.alienRefundTime   = _alienRefundTime;

        if (_hashedSecret == bytes32(0)) {
            t.isSettled  = true;
            t.isRefunded = true; // closed: nothing further can be transferred
            emit AlienSettled(_drexTxId, _slot, _index);
        } else {
            emit AlienLocked(_drexTxId, _slot, _index);
        }
    }

    // Hash-lock mode: Mike claims y with the secret Alice revealed on R.
    // Allowed only before T_A, so it can never race Alice's refund.
    function mikeSettleTrade(bytes32 _txId, bytes32 _secretRevealed) external nonReentrant {
        TxStatus storage t = transactions[_txId];
        require(t.hashedSecret != bytes32(0), "This is not a HTLC transaction");
        require(!t.isSettled, "Trade already settled");
        require(!t.isRefunded, "Funds already have been refunded");
        require(block.timestamp <= t.alienRefundTime, "Claim window has closed");
        require(keccak256(abi.encodePacked(_secretRevealed)) == t.hashedSecret,
            "Secret is not equal to Hashed Secret");

        t.isSettled = true;
        t.isRefunded = true;
        require(_pay(t.tokenContract, t.mikeAddress, t.alienAmount), "Transfer to Mike failed");
        emit AlienSettled(_txId, t.slotNumber, t.txIndex);
    }

    // Hash-lock mode: Alice reclaims y after T_A if Mike has not claimed it.
    function aliceGetRefund(bytes32 _txId) external nonReentrant {
        TxStatus storage t = transactions[_txId];
        require(t.hashedSecret != bytes32(0), "This is not a HTLC transaction eligible for refund");
        require(!t.isRefunded, "Funds already have been refunded");
        require(!t.isSettled, "Trade already settled");
        require(block.timestamp > t.alienRefundTime,
            "Refund is not yet available to Alice because expiration has not been achieved");

        t.isRefunded = true;
        require(_pay(t.tokenContract, t.aliceAddress, t.alienAmount), "Refund to Alice failed");
        emit AlienRefunded(_txId, t.aliceAddress);
    }

    function _pay(address _token, address _to, uint256 _amount) private returns (bool success) {
        if (_token == address(0)) {
            (success,) = payable(_to).call{value: _amount}("");
        } else {
            success = IERC20(_token).transfer(_to, _amount);
        }
    }

    /// @notice Number of leaves in a slot's tree (needed to verify a proof on R).
    function getSlotSize(uint256 _slotNumber) public view returns (uint256) {
        return chainConfirmedTx[_slotNumber].length;
    }

    /// @notice Read-only Merkle construction for a CLOSED slot.
    /// isProof = false → returns [committedRoot]
    /// isProof = true  → returns the sibling path of leaf `_proofIndex`
    /// For large slots, rebuild the tree off-chain from AlienSettled/AlienLocked events
    /// (the gas of this call grows linearly with the slot size; see Section 8.3).
    function createMerkleTree(uint256 _slotNumber, bool isProof, uint256 _proofIndex)
        public view returns (bytes32[] memory)
    {
        require(isSlotClosed(_slotNumber), "Slot is not closed yet");
        bytes32[] memory _data = chainConfirmedTx[_slotNumber];
        require(_data.length > 0, "No data to create Merkle tree");
        if (isProof) return ListrackMerkle.proof(_data, _proofIndex);
        bytes32[] memory _root = new bytes32[](1);
        _root[0] = ListrackMerkle.committedRoot(_data);
        return _root;
    }

    function getTradeFeatures(bytes32 _txId) public view returns (TxStatus memory) {
        return transactions[_txId];
    }
}

contracts/DrexListrack.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24; 

    import {ReentrancyGuard} from "./utils/ReentrancyGuard.sol";
    import {ListrackMerkle} from "./ListrackMerkle.sol";
    import "hardhat/console.sol";
    //import "./utils/console.sol";

    // ATTENTION TO OVERFLOW!!! STILL REQUIRES AUDIT
    //import "./utils/math.sol";
   
    // common interface to Token Contracts
    interface IERC20 {
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function allowance(address owner, address spender) external returns (uint256);
        }

    // interface to DrexMerkle, which votes for Merkle Root of transactions in Alien Chain
    // the function returns a confirmation bytes4 and the Merkle Root of transactions (bytes32)
    interface IgetMerkleRoot {
    function getRootByBlock (uint256 blockNumber) external view returns (bytes4, bytes32);
    }

    // Alice is the name of the user which holds Alien (external) coins
    // Mike is the name of the user which holds Drex coins (Brazilian CBDC)

    // Alien Chain is a external blockchain
    // Drex chain is the permissioned ledger of Brazilian CBDC

    // !!! Mike must have previously approved transfer to current smart contract whether using tokens
    // !!! Mike must have previously approved transfer to current smart contract whether using tokens
    // The Script Test does this task

    // Each agreement between Alice and Mike also involves agreeing in a trustful Merkle Contract
    // The users have the choice to select the most proper trustful nodes that are going to listen
    // to the Alien Chain (Merkle Contracts)
    // Each trade can have several Merkle Contract to enhance trust and reliability

    // Each Trade has its own TxId, which is unique and replicable in Alien Chain
    // Trades are inserted in a chain, with its TxId as a result from previous TxId plus hashed fields
    // The chain ensures that indexes can be monitored in Alien Chain, ensuring that they can only
    // be inserted whether they are not expired yet

    // transactions are clustered in time slots, which reproduce the usual expiration times
    // each time slot has a Transaction which is the head of the slot
    // the head of the slot is a Tx Index that is monitored by voting in Alien Chain, allowing or not
    // new transactions. The vote process is based on succesfull locks or transfers

    // The upper limits for expirations deadlines in DrexListrack are fixed => they are not set by users
    // The fixed time allows to create a chain of transactions in Drex that can be used in alien chain 
    // The slot time in Alien Chain is also fixed, following Drex parameters

    contract DrexListrack is ReentrancyGuard {

    // this event happens when a Trade is Inserted, showing the users and its TxId
    event tradeInsertedUsersTxId    (address indexed aliceDrexAddress,
                                    address indexed mikeDrexAddress,
                                    bytes32 indexed TxId);

    // this event happens when a Trade is inserted, showing the TxId, its position in Drex chain
    // and the previous TxId in the Drex Chain
    event tradeInsertedTxId         (bytes32 indexed previousTxId,
                                    uint256 indexed txIndexDrex,
                                    bytes32 indexed TxId);

    // Event to emit when a new lot is produced and generates a slot head transaction
    // this slot head in a time slog allows inserting or not new transaction in alien chain
    event drexIndexAlienConfirmation    (uint256 indexed drexAlienIndexConfirmation);
                               // uint256 indexed drexAlienIndexConfirmationBlock);

    // Event to emit when a TxId is locked in Drex by Mike
    event lockedTxId (bytes32 indexed TxId);

    // Event to emit when a TxId is manually settled using secret hash
    event manualSecretTradeSettled(bytes32 indexed TxId, bytes32 indexed SecretRevealed);

    // Event to emit when a TxId is manually settled
    event manualTradeSettled(bytes32 indexed TxId);

    // Event to emit when a TxId is settled using Merkle Contracts
    event automaticTradeSettled(bytes32 indexed TxId);

    // Event to emit when a TxId is reverted returning funds back to Mike
    event tradeReverted(bytes32 indexed TxId);


    struct SlotStatus {
        // Time struct holding information of slot time production

        // this feature holds the lowest index of Tx that is still capable of being
        // inserted in Alien Chain
        // if a Trade holding a TxIndex lower than this this LowerLimit is inserted in alien chain
        // the transaction is reverted
        uint256 lowerLimitDrexIndexAlienConfirmation;
        uint256 currentSlot;
        uint256 genesisSlot;
        uint256 lastTimeStamp; 
        uint256 currentTxIndex;
    }

    struct StatusChain {
        // status of each Tx in Drex chain of transactions
        bool    locked;
        bool    settled;
        uint256 slotNumber;
        uint256 chainPosition;
        bytes32 previousChainTxId;
    }
        
    // Structure to hold trade details
    struct Trade {
        address     aliceDrexAddress;
        address     mikeDrexAddress;

        // drexToken address, which can be digitalReal or other DrexToken
        // if address(0), the Trade involves only native Drex (wholesale Drex)
        address     drexTokenAddress;

        bytes32     drexHashFields;  
        address     aliceAlienAddress;
        address     mikeAlienAddress;

        // alienToken address, which can be any token in alien Chain
        // if address(0), the Trade involves only native coins in Alien Chain (e.g Ether)
        address     alientokencontract;

        uint256     drexAmount;
        uint256     alienAmount;

        // hashed secret is the hash of a secret that is hashed again
        // for inserting in Listrack
        // secret hash is hashed twice for ensuring that the input is bytes32 input
        // this is used for a boosted HTLC without common risks such as syncronization
        bytes32     hashedSecret;
        
        // Drex Merkle Contract is a array of trustful smart contracts in Drex that listen to alien chain
        // this list of Merkle contracts is a agreement between Alice and Mike
        // if one contract fails to confirm the transaction, the following can make this confirmation
        // only trustfull contracts can be included in this list, which are kept by Drex Nodes
        address[]   drexMerkleContract;

        // status of the Tx, informing whether it is locked, settled,
        // position in the chain, previous TxId in Drex Chain and the slot number it belongs
        StatusChain statusChain;

        // deadlines on E, computed at registration and bound into TxId:
        // T_E (last moment Alice may write her leg) and T_A (hash-lock refund time)
        uint256     alienDeadline;
        uint256     alienRefundTime;
    }

    //** TIME VARIABLES **//

    // time Slot mimics the behavior of creating blocks, classifying transactions
    // in groups that are clustered by time periods
    uint256 timeSlot;

    // start of the genesis slot of the genesis-anchored slot clock
    uint256 public genesisTimestamp;

    // Slot features containing 
    // currentSlotNumber, genesisSlot, lastTimeStamp and
    // lowerLimitDrexConfirmation Index in chainDrexTx for keeping alien chain syncronized
    // with the updated index in chainDrexTx still capable of confirming a Tx in alien chain
    SlotStatus public slotProduction;

    // Drex Leg in slots defined by constructor
    uint256 public drexLegExpiration;

    // Alien confirmation in slots required for confirming a transaction in alien chain
    uint256 private alienConfirmation;

    // listrackExpiration in slots required for cancelling a Listrack transaction in both chains
    uint256 private listrackExpiration;

    bool leftIndex_0 = false;
    // this boolean controls update Chain when the block head index moves to a number rather than zero
    
    // ** TRADE VARIABLES ** //

    // this mapping stores pending transactions in Listrack
    // pending transactions : _hashFields (fields of Tx without _secretHash and Tx position) => Tx_Id 
    // TxId = previous TxId + _hashFields Position (_hashFields + TxIndex + _secretHash)
    // this variable is required for not storing the same Tx twice, which is ensured by _hashFields (key)
    mapping (bytes32 => bytes32) public pendingTransactions;

    // Mapping to track the trades
    // bytes 32 is TxId
    mapping (bytes32 => Trade) internal trades; // read through getDrexAlienInputsbyId

    // chain that registers Listrack transactions in Drex
    // this chain avoids double spending // this chain stores every Tx in Drex
    bytes32[] public chainDrexTx;

    // _chain TxId of the previous chainDrexTx
    bytes32 private previousChainTxId; 
    
    // mapping for slot heads
    // each slot head contains the TxIndex of chainDrexTx that initiates that slot
    // slot number => index of Tx in chainDrexTx
    mapping (uint256 => uint256) slotHeadTxIndex;

    // transactions structured by public key of the counterparties
    // it links counterparty address => array of Tx Ids
    mapping (address => bytes32[]) public transactionsbyUser;

   
    // ** MERKLE CONTRACTS VARIABLES **//

    // mapping that stores for each Merkle Contract specific slots that contain
    // all expiring TxIds that expire in that slot
    // Merkle Contract => Slot Number => Array with TxIds that expires in that slot
    mapping (address => mapping (uint256 => bytes32[])) private merkleContractRevert;

    // mapping that stores the latest slot number that was subject to confirmation by
    // a Merkle Contract
    // as each Tx is confirmed and settled by each Merkle Contract,
    // it updates the last confirmed slot of those Txs in order to revert old transactions
    // this variable restricts confirmed slots only by the Merkle Contracts that are allowed
    // by the counterparties to do such task
    // mapping (address => uint256) private lastConfirmedSlotByMerkleContract;

    // it stores the last Reverted Slot by each Merkle Contract
    mapping (address => uint256) private lastRevertedSlotByMerkleContract;

    // ** CONSTRUCTOR ** //
    constructor (uint256 _timeSlot, uint256 _drexLegExpiration, 
                uint256 _alienConfirmation, uint256 _listrackExpiration) payable {
        
        // timeSlot => time in seconds to group a number of transactions in Drex
        // that mimics a block

        // Drex Leg Expiration => time in slots that the Drex Leg expires

        // Alien Confirmation => time in slots that Alien Leg must be confirmed
        // it must be greater than 3* Drex Leg Expiration | IT INCLUDES DREX LEG

        // Listrack Expiration => time in slots that Listrack is cancelled in both chains

        //              => Drex Leg  | =>=>  Alien Leg | =>=>=>=> Listrack  Expiration |
        //                 1 slot    |2 slots          |  3 slots                      |
        //Time Ellapsed    1 slot    |3 slots ellapsed |  6 slots ellapsed             |
        //Time Ellapsed        Alien Confirmation      |  Alien Leg Expiration         |
        //Time Ellapsed                       Alien Expiration                         |
        
        // timeSlot mimics a block production based on time
        // it classifies transactions in block times for reverting 
        // and other related transactions

        require (_alienConfirmation >= 3*_drexLegExpiration,"Alien Confirmation must be at least 3 times Drex Leg");
        require (_listrackExpiration >= 2*_alienConfirmation,"Alien Expiration must be at least 6 times Drex Leg");

        timeSlot = _timeSlot;  // in seconds

        // drexLegExpiration in slots
        drexLegExpiration = _drexLegExpiration;
        
        // drexLegConfirmation in slots
        alienConfirmation = _alienConfirmation;
        
         // drexLegExpiration in slots
        listrackExpiration   = _listrackExpiration;
       
        // current slotNumber for constructor is a number > 0
        // to avoid overflow in negative numbers
        slotProduction.currentSlot = listrackExpiration+1; 
        // other setup functions for Slot are done below
        slotProduction.genesisSlot = slotProduction.currentSlot;
        slotProduction.lowerLimitDrexIndexAlienConfirmation = 0;
        slotProduction.lastTimeStamp = block.timestamp;
        genesisTimestamp = block.timestamp;
        // C1: the settlement deadline T_S (70% of T_X) must leave room after T_E
        require (((_listrackExpiration*7000)/10000) > _alienConfirmation, "Settlement window must exceed Alien Confirmation");

        slotHeadTxIndex[slotProduction.currentSlot] = 0;

        console.log ("@@@ Drex Listrack deployed at Slot : " ,slotProduction.currentSlot);

    }

    // Function for ANYONE TO SET SPECIFIC TX DETAILS BETWEEN COUNTERPARTIES
    // the function allows anyone to set trade details 
    // ANYONE as a msg.sender can allow smart contracts to set trades
    function setTrade(
        // 3 addresses: Alice, Mike, DrexToken
        address [] memory _drexAddresses,
        // address _aliceDrexAddress,
        // address _mikeDrexAddress,
        // address _drexTokenAddress,  // drex token contract to transfer Drex Tokens
        uint256 _drexAmount,
        address[] memory _drexMerkleContract,
        // 3 addresses: Alice, Mike, AlienToken
        address [] memory _alienAddresses, 
        //address _aliceAlienAddress,
        //address _mikeAlienAddress,
        //address _alientokencontract, // alien contract to transfer Alien tokens
        uint256 _alienAmount,
        // _hashedSecret is required for boosted HTLC transactions
        bytes32 _hashedSecret
        
    ) external payable {
       // it does not require to be NonReentrant because the same msg.sender
       // can send the same TxId several times - only the last one one will be considered
       // the most important is that this function does not transfer funds
       // MikeAgree trade locks funds to DrexListrack, but is not required to be NonReentrant
       // because it will not accept to lock a transaction already locked
       

        require(_drexAmount > 0, "Invalid Drex amount");
        require(_alienAmount > 0, "Invalid Alien amount");

        bytes32 _drexHashFields = bytes32(0);
       
        // hashing the  Merkle Contract List
        require (_drexMerkleContract.length!=0,"At least One Master Merkle Contract is required");
        for (uint256 i=0; i < _drexMerkleContract.length;i++) {
            _drexHashFields = keccak256(abi.encodePacked(
            _drexHashFields,_drexMerkleContract[i]));  
        }
        
        // hashing drexHashFields that is required as a input in AlienListrack
         _drexHashFields = keccak256(
            abi.encodePacked(
                _drexAddresses[0],
                _drexAddresses[1],
                _drexAddresses[2],
                _drexAmount,
                _drexHashFields
            )
        );  

            //console.log ("First Hash");
            //console.logBytes32(_drexHashFields);
            //console.log("Chain Pending Tx length - This is the position",(chainDrexTx.length));
        
        bytes32 _hashFields = keccak256(
            abi.encodePacked(
                _drexHashFields,
                _alienAddresses[0],
                _alienAddresses[1],
                _alienAddresses[2], // alien contract to transfer tokens
                _alienAmount  // _nonce
            )
        );  // _counter,

        updateChain();
        // deadlines on E, as timestamps of the genesis-anchored clock:
        // T_E = registration slot start + alienConfirmation slots
        // T_A = registration slot start + listrackExpiration slots (> T_S, condition C3)

        bytes32 _hashFieldsPosition = keccak256(
            abi.encodePacked(
                _hashFields,
                // hashedSecret is hashed here to avoid two identical txs in Pending Transactions
              _hashedSecret,
               chainDrexTx.length,
               alienDeadlineNow(),
               alienRefundTimeNow()
            )
        );  // _counter,

        // HASHES FOR TX IDS
        // hash of Drex Fields + Hash of Alien Fields + Hash of Tx Index = Hash TxIndex

        //  console.log ("Pending Hash_Fields");
        //  console.logBytes32(_hashFields);

         if (chainDrexTx.length==0) {
        previousChainTxId = _hashFieldsPosition;   
        } else {
        previousChainTxId = chainDrexTx[chainDrexTx.length-1];
        }

        // the below code is the chain of Pending Transactions
        // using the previous Id hashed with the current Hash of Input Fields of Set Trade
         bytes32 _txId = keccak256(
            abi.encodePacked(
                previousChainTxId,
                _hashFieldsPosition  // Id is built using last Id of the previous transaction
            )
        ); 


        //console.log ("Hashes Ok | _hashFields :");
        //console.logBytes32 (_hashFields);

        //console.log ("Hashes Ok | _hashFieldsPosition :");
        //console.logBytes32 (_hashFieldsPosition);

        //console.log ("Hashes Ok | Tx Id :");
        //console.logBytes32 (_txId);

        // registering the transaction in the mapping hash_Fields => _txId
        // at first if verifies if transaction is already registered as pending transaction
        if (pendingTransactions[_hashFields]==bytes32(0)) {
            // this block occurs if this transaction is not registered yet in Pending Transactions

            // stores the Tx Fields in pendingTransactions
            pendingTransactions[_hashFields]=_txId;

            // stores the pending transaction in chainDrexTx
            chainDrexTx.push(_txId);
           
            } else {
            // it only applies for transactions with same hash 
            // it verifies whether current Pending Transaction can be replaced by another

            require (!trades[pendingTransactions[_hashFields]].statusChain.locked,
                    "Transaction already locked");
            
            require (slotProduction.currentSlot - 
                    trades[pendingTransactions[_hashFields]].statusChain.slotNumber >
                    drexLegExpiration,
            // transaction can only be replaced whether drexExpiration has been achieved!
            // transaction can only be replaced whether there isn't another in standby before expiration
            // it only applies for transactions with same hash containing same fields
            // it avoids replicating the same transaction in different TxIds and 
            // prevents Mike from Locking funds in two identical transactions with different TxIds
                    "The same transaction cannot be inserted while waiting for lock");
            
            // stores the Tx Fields in pendingTransactions
            pendingTransactions[_hashFields]=_txId;

            // stores the pending transaction in chainDrexTx
            chainDrexTx.push(_txId);
            }

        transactionsbyUser[_drexAddresses[0]].push(_txId);
        transactionsbyUser[_drexAddresses[1]].push(_txId);
        

        //console.log ("Chain Pending Tx updated : new length: ", chainDrexTx.length);
        //console.log ("Position of the current Trade is length : ",chainDrexTx.length-1);
        //console.log ("Beginning to register the trade");

        trades[_txId] = Trade({
            aliceDrexAddress            : _drexAddresses[0],
            mikeDrexAddress             : _drexAddresses[1],
            drexTokenAddress            : _drexAddresses[2],
            drexMerkleContract          : _drexMerkleContract,
            drexHashFields              : _drexHashFields,
            aliceAlienAddress           : _alienAddresses[0],
            mikeAlienAddress            : _alienAddresses[1],
            drexAmount                  : _drexAmount,
            alienAmount                 : _alienAmount,
            alientokencontract          : _alienAddresses[2],
            hashedSecret                : _hashedSecret,
            statusChain                 : StatusChain({ locked:false,settled:false,
                                                       chainPosition:chainDrexTx.length-1,
                                                        previousChainTxId : previousChainTxId, 
                                                        slotNumber:slotProduction.currentSlot}),
            alienDeadline               : alienDeadlineNow(),
            alienRefundTime             : alienRefundTimeNow()
        }) ;

        //  console.log("Position of the Trade in the chain Id : ", 
        //  trades[_txId].statusChain.chainPosition);

        //  console.log("Drex Merkle Contract One",trades[_txId].drexMerkleContract[0]);
        //  console.log("Drex Merkle Contract Two",trades[_txId].drexMerkleContract[1]);

     //   console.log         ("# Trade Registered :");
     //   console.logBytes32  (_txId);

        // the below code is required for properly updating the chain
        slotProduction.currentTxIndex = chainDrexTx.length-1;  // CHANGED

        // Mike can automatically lock transaction whether he is the sender
        if (msg.sender == _drexAddresses[1]) {
            mikeAgreeTrade (_txId);
            // if Mike does not have enough funds the transaction is not either
            // registered (set) or locked because mikeAgreeTrade has require functions inside
        }   else {
         //   updateChain (chainDrexTx.length-1);   // CHANGED
            }

        // Event are only emitted whether every require succeeds in previous statements
        emit tradeInsertedUsersTxId     (_drexAddresses[0],_drexAddresses[1],_txId);
        emit tradeInsertedTxId          (previousChainTxId,chainDrexTx.length-1,_txId);
        
        //console.log ("Drex Hash Fields");
        //console.logBytes32 (_drexHashFields);
        //console.log ("Drex Previous Id");
        //console.logBytes32 (previousChainTxId);
        //console.log ("Drex Tx Index", chainDrexTx.length-1);
        //console.log ("Drex Tx Id");
        //console.logBytes32 (_txId);
       // console.log ("Drex Alien Confirmation Index",
       // slotProduction.lowerLimitDrexIndexAlienConfirmation);
    }

    // Function for Mike to agree on Alice's terms and lock his DREX
    function mikeAgreeTrade (bytes32 _txId) public payable { // nonReentrant
    // mikeAgreeTrade does not require to be nonReentrant because the risk belongs to Mike
    //  returns (bool) {
        bool _success = false;
        // clean storage trade eventually 

        require(trades[_txId].aliceDrexAddress != address(0), "Trade does not exist");
        require(trades[_txId].mikeDrexAddress == msg.sender, "Unauthorized to lock funds");
        require(!trades[_txId].statusChain.locked, "Trade is already locked");

        updateChain();

        // verifying if transaction is not expired yet for Drex leg
        require((slotProduction.currentSlot-trades[_txId].statusChain.slotNumber)
                < drexLegExpiration ,"Drex leg already expired");

        // transfer to current smart contract
        if (trades[_txId].drexTokenAddress == address(0)) {
            require(msg.value == trades[_txId].drexAmount, "Incorrect DREX amount sent");
            _success = true; // msg.value is already held by this contract
            } else {
            uint256 _allowance = IERC20(trades[_txId].drexTokenAddress).allowance(
                                msg.sender,address(this));
            require (_allowance>=trades[_txId].drexAmount, 
            "Drex Listrack was not previously allowed to transfer tokens");
            // mike must have previously allowed his token contract to transfer to DrexListrack.sol
            
            _success = IERC20(trades[_txId].drexTokenAddress).transferFrom(
            msg.sender,payable(address(this)),trades[_txId].drexAmount);
        }
        if (_success) {
        trades[_txId].statusChain.locked = true;
    
        if (trades[_txId].hashedSecret==bytes32(0)) {
        storeTxIdPerMerkleContractToRevert(_txId); 
        // merkle contracts are only valid for non HTLC transactions
        // the function above allows Merkle Contracts to make automatic operations
        } 
        emit lockedTxId(_txId);
        // updateChain (trades[_txId].statusChain.chainPosition); // CHANGED
        // slotProduction.currentTxIndex = trades[_txId].statusChain.chainPosition;
        //console.log ("!!!!!!!! LOCKED Transaction Successful : ");
        //console.logBytes32(_txId);
        }
        // return (_success);
    }

        // Alice confirms a trade informing Merkle Tree
        // Alice (or any relayer) settles by proof. _leafCount is the size of the slot's
        // tree (AlienListrack.getSlotSize), which the committed root binds.
        // The settlement window T_S applies in BOTH modes, so settlement on R can never
        // race Mike's refund, which opens only at T_X > T_S (condition C2).
        function aliceSettleTrade(bytes32 _txId, uint256 _txIndex, uint256 _leafCount,
        bytes32[] memory _merkleProof, uint256 _blockNumber, bytes32 _secretRevealed)
        public payable nonReentrant {
        bool success = false;
        Trade memory trade = trades[_txId];
        require(trade.aliceDrexAddress != address(0), "Trade does not exist");
        require(trade.statusChain.locked, "Trade is not locked");
        require(!trade.statusChain.settled, "Trade already settled");
        updateChain();
        require(withinSettlementWindow(trade.statusChain.slotNumber), "Alien Leg already expired");
        require (validateMerkleProof (_txId, _txIndex, _leafCount, _merkleProof, _blockNumber),
        "Transaction not settled in Alien Chain");
        if (trade.hashedSecret!=bytes32(0)) {
        require (keccak256(abi.encodePacked(_secretRevealed)) == trade.hashedSecret,
         "Secret Hashed is not equal to Hashed Secret of the Transaction");
        }
        trades[_txId].statusChain.settled = true; // Mark the trade as settled
        trades[_txId].statusChain.locked = false; // There are no more locked assets in Listrack
        if (trade.drexTokenAddress == address(0)) {
            (success,)= payable(trade.aliceDrexAddress).call{value: trade.drexAmount}("");
            } else {
            success = IERC20(trade.drexTokenAddress).transfer(payable(trade.aliceDrexAddress),
            trade.drexAmount);
            }
        require(success, "Transaction settlement failed");
        if (trade.hashedSecret!=bytes32(0)) {
            emit manualSecretTradeSettled (_txId,_secretRevealed);
        } else  emit manualTradeSettled (_txId);
    }

    // settlement deadline T_S = 70% of T_X, counted in slots from registration
    function withinSettlementWindow (uint256 _registrationSlot) private view returns (bool) {
        return (slotProduction.currentSlot - _registrationSlot) < ((listrackExpiration*7000)/10000);
    }

    // start time of a slot of the genesis-anchored clock
    function slotStartTime (uint256 _slot) public view returns (uint256) {
        return genesisTimestamp + (_slot - slotProduction.genesisSlot) * timeSlot;
    }

    // T_E and T_A for a trade registered in the current slot (see setTrade)
    function alienDeadlineNow () private view returns (uint256) {
        return slotStartTime(slotProduction.currentSlot) + alienConfirmation*timeSlot;
    }
    function alienRefundTimeNow () private view returns (uint256) {
        return slotStartTime(slotProduction.currentSlot) + listrackExpiration*timeSlot;
    }

    // current slot of the genesis-anchored clock
    function slotNow () public view returns (uint256) {
        return slotProduction.genesisSlot + (block.timestamp - genesisTimestamp) / timeSlot;
    }

    // Batch settlement submitted by a nominated committee contract after it has
    // verified the trades against its own stored root (MerkleContract).
    function sendTxForSettlement(bytes32[] memory _transactions)
    external payable nonReentrant
        {
        updateChain();
        for (uint256 i=0; i< _transactions.length ; i++) {
        bool _success = false;
        if (!isValidMerkleContract(_transactions[i],msg.sender)) continue;
        Trade memory trade = trades[_transactions[i]];
        if (trade.hashedSecret != bytes32(0)) continue; // hash-lock trades need the secret
        if (trade.aliceDrexAddress == address(0)) continue;
        if (!trade.statusChain.locked) continue;
        if (trade.statusChain.settled) continue;
        if (!withinSettlementWindow(trade.statusChain.slotNumber)) continue; // T_S passed
        trades[_transactions[i]].statusChain.settled = true;
        trades[_transactions[i]].statusChain.locked = false;
        if (trade.drexTokenAddress == address(0)) {
            (_success,)= payable(trade.aliceDrexAddress).call{value: trade.drexAmount}("");
            } else {
            _success = IERC20(trade.drexTokenAddress).transfer(payable(trade.aliceDrexAddress),trade.drexAmount);
            }
        if (_success) {
            emit automaticTradeSettled(_transactions[i]);
        } else {
            trades[_transactions[i]].statusChain.settled = false;
            trades[_transactions[i]].statusChain.locked = true;
        }
        }
    }

    // function to revert Mike locked Funds whether funds have expired due to
    // Listrack expiration
    function mikeManualRevert (bytes32 _txId) external payable nonReentrant {
        bool success = false;
        
      //  require(trades[_txId].mikeDrexAddress == msg.sender,
      //   "Unauthorized - Only Mike can revert");
      // anyone can revert the Mike Tx whether he has this right to receive

      console.log ("Entered Manual Revert : Trade Id");
      console.logBytes32(_txId);
         
        require(!trades[_txId].statusChain.settled, 
        "Trade already settled");

        require(trades[_txId].statusChain.locked, 
        "Trade not locked yet to revert");

        //console.log (">> Current Slot :",slotProduction.currentSlot);
        //console.log (">> Tx Slot :", trades[_txId].statusChain.slotNumber);
        //console.log (">> Listrack Expiration :", listrackExpiration);

        updateChain();
        require((slotProduction.currentSlot-trades[_txId].statusChain.slotNumber)
                >= listrackExpiration ,"Listrack transaction not expired yet");
        
        if (trades[_txId].drexTokenAddress == address(0)) {
            (success,)= payable(trades[_txId].mikeDrexAddress).call
            {value:trades[_txId].drexAmount}("");
            } else {
            success = IERC20(trades[_txId].drexTokenAddress).transfer(
            payable(trades[_txId].mikeDrexAddress),trades[_txId].drexAmount);
            }
        if (success) {
        trades[_txId].statusChain.locked = false; 
        trades[_txId].statusChain.settled = false;
        emit tradeReverted(_txId);
        }
    }

    function revertTransaction (bytes32 _txId) private
        returns (bool) {
        bool success = false;
        StatusChain storage _st = trades[_txId].statusChain;
        if (_st.locked && !_st.settled &&
            (slotProduction.currentSlot - _st.slotNumber) >= listrackExpiration) {
            // state first: a refunded trade can be neither refunded again nor settled
            _st.locked = false;
            if (trades[_txId].drexTokenAddress == address(0)) {
                (success,)= payable(trades[_txId].mikeDrexAddress).call
                {value:trades[_txId].drexAmount}("");
            } else {
                success = IERC20(trades[_txId].drexTokenAddress).transfer(
                payable(trades[_txId].mikeDrexAddress),
                trades[_txId].drexAmount);
            }
            if (success) emit tradeReverted(_txId);
            else _st.locked = true; // transfer failed: leave the trade refundable
        }
        return (success);
    }
    
    function revertTxsbyMerkleContract (address _merkleContract)
    external nonReentrant {
        // Batch refund of expired plain-mode trades that nominated _merkleContract.
        // Trades are indexed by their refund slot s0 + T_X, so every index up to the
        // current slot is due.
        updateChain();
        uint256 _upperLimitSlotToRevert = slotProduction.currentSlot;
        uint256 _from = lastRevertedSlotByMerkleContract[_merkleContract] + 1;
        if (_from < slotProduction.genesisSlot) _from = slotProduction.genesisSlot;
        for (uint256 i = _from; i <= _upperLimitSlotToRevert; i++) {
            for (uint256 j = 0; j < merkleContractRevert[_merkleContract][i].length; j++) {
                revertTransaction(merkleContractRevert[_merkleContract][i][j]);
            }
        }
        if (_upperLimitSlotToRevert > lastRevertedSlotByMerkleContract[_merkleContract])
            lastRevertedSlotByMerkleContract[_merkleContract] = _upperLimitSlotToRevert;
    }

    function isValidMerkleContract (bytes32 _txId, address _merkleContract)
    private view returns (bool) {
    bool _success = false;
        for (uint i=0 ; i < trades[_txId].drexMerkleContract.length ; i++) {
        if (trades[_txId].drexMerkleContract[i] == _merkleContract) {
            _success = true;
            break;
        }
        }
    return _success;
    }


    // Folds the proof into the committed slot root (ListrackMerkle) and accepts it if
    // ANY nominated committee has stored that root for the slot (OR rule: safety is
    // that of the weakest nominated committee, liveness that of the strongest).
    function validateMerkleProof (bytes32 _txId, uint256 _txIndex, uint256 _leafCount,
    bytes32[] memory _merkleProof, uint256 _blockNumber) public view returns (bool) {
        (bool _ok, bytes32 _root) = ListrackMerkle.computeRoot(_txId, _txIndex, _leafCount, _merkleProof);
        if (!_ok) return false;
        bytes4 _magicNumber = 0x1626ba7e;
        for (uint256 i = 0; i < trades[_txId].drexMerkleContract.length; i++) {
            (bytes4 _successfullCall, bytes32 _returnedRoot) =
                IgetMerkleRoot(trades[_txId].drexMerkleContract[i]).getRootByBlock(_blockNumber);
            if (_successfullCall == _magicNumber && _returnedRoot == _root) return true;
        }
        return false;
    }

    function  storeTxIdPerMerkleContractToRevert (bytes32 _txId) private {
        for (uint256 i=0; i<trades[_txId].drexMerkleContract.length ; i++) {
            // a single TxId can have several Merkle Contracts attached to it
            // which can be in charge for reversals and settlements
            //it defines that each Merkle Contract has several txId attached to it
            // each txId can have several Merkle Contracts attached to it
        //console.log ("!!! Slot Number to Store Revert:", trades[_txId].statusChain.slotNumber+listrackExpiration);
        merkleContractRevert[trades[_txId].drexMerkleContract[i]]
        [trades[_txId].statusChain.slotNumber+listrackExpiration].push(_txId);

        /*
        console.log ("!!!Transaction trying to push to MerkleContractRevert");
        console.logBytes32 (_txId);
        console.log ("!!!Last Id of transaction pushed must equal to _txId given above");
        console.logBytes32 (merkleContractRevert[trades[_txId].drexMerkleContract[i]]
        [trades[_txId].statusChain.slotNumber+listrackExpiration]
        [merkleContractRevert[trades[_txId].drexMerkleContract[i]]
        [trades[_txId].statusChain.slotNumber+listrackExpiration].length-1]);
        */
        
        }
    }

    function getTxIdbyUser (address _user) external view returns (bytes32[] memory) {
        return (transactionsbyUser[_user]);
    }

    function getDrexAlienInputsbyId (bytes32 _txId) external view returns 
    (Trade memory,uint256) {
        return (trades[_txId],
        slotProduction.lowerLimitDrexIndexAlienConfirmation);
    }

      function updateChain () private {

        uint256 _ellapsedTime = block.timestamp - slotProduction.lastTimeStamp;
        console.log (">>> Ellapsed Time: ", _ellapsedTime);
        // all code below depends on a new block production

        console.log ("Current Slot: ", slotProduction.currentSlot);

        if (slotNow() > slotProduction.currentSlot) {
        console.log (">>> Creating new time slot");
        // for each new slot produced the head of the slot is written
        // console.log ("Creating new time slot");
        console.log (">>> Old Slot: ", slotProduction.currentSlot);   
        slotProduction.currentSlot = slotNow(); // genesis-anchored: no drift across empty slots
        // it increases the slot time by one in order to classify transactions
        console.log (">>> New Slot after Ellapsed Time Update: ", slotProduction.currentSlot);

        uint256 lowerLimitSlotAlienConfirmation = 
        slotProduction.currentSlot - alienConfirmation;

        // each block head of a slot contains the first transaction that
        // initiated this algorithm for reverting transactions and
        // and confirming transactions in Alien Chain through sending that indexId to
        // Alien Chain
        slotHeadTxIndex[slotProduction.currentSlot] = slotProduction.currentTxIndex;
        console.log (">>> New Slot Head Index after New Slot Created : ", (slotHeadTxIndex[slotProduction.currentSlot]));
        //console.log ("New blockHead Tx Id : ");
        //console.logBytes32 (blockHead[block.number].TxId);
            // at least a minimum number of blocks must happen before emitting the event in the blockchain
            // the blockhead must exist to emit the event in blockchain
            // this is to avoid the first slots that are not yet to be expired
            // 1000 is the minimum slot to be considered in the slot chain

      //  console.log ("Before Loop");
          //  console.log ("LowerLimitSlot before Loop",lowerLimitSlotAlienConfirmation);
      //  console.log ("Genesis Slot:", slotProduction.genesisSlot);
        
        // the below statement asserts that slots before the genesis slot are not considered
        if    (lowerLimitSlotAlienConfirmation>slotProduction.genesisSlot) {
            // if the head transaction is indexed as zero, the following instructions cannot happen
                // if the head transaction is indexed as zero, the following instructions cannot happen
            console.log ("LowerLimitSlot before Loop",lowerLimitSlotAlienConfirmation);
            while ((slotHeadTxIndex[lowerLimitSlotAlienConfirmation] == uint256(0))){ 
            if (!leftIndex_0) {
                leftIndex_0 = true;
                break;
                // next time in this loop a new slot will be created whose index cannot be zero anymore
            }
            // || (slotHeadTxIndex[lowerLimitSlotAlienConfirmation] == slotProduction.lowerLimitDrexIndexAlienConfirmation)) 
            console.log (">>> Drex Index to update: ",slotHeadTxIndex[lowerLimitSlotAlienConfirmation]);
            console.log (">>> Current Drex Index :", slotProduction.lowerLimitDrexIndexAlienConfirmation);
                lowerLimitSlotAlienConfirmation++;  
            //  console.log ("Not leaving loop");
            console.log ("Lower Limit Slot Alien Confirmation changing in Loop: ", lowerLimitSlotAlienConfirmation);
                // it is required to find the oldest slot of transactions to expire
            }
            
            // the code below updates the Tx Index which expires in alien confirmation blocks
            // the blockProduction index is lower than the current one 
            // because it will expire in the future
           // if (slotHeadTxIndex[lowerLimitSlotAlienConfirmation]!=uint256(0)) {
            slotProduction.lowerLimitDrexIndexAlienConfirmation = 
            slotHeadTxIndex[lowerLimitSlotAlienConfirmation];
          //  } 
            console.log("New Alien Contirmation Tx Index to Expire in Future: "
            , slotProduction.lowerLimitDrexIndexAlienConfirmation);
            emit drexIndexAlienConfirmation (slotProduction.lowerLimitDrexIndexAlienConfirmation);
        }
        // below is the code when achieving window time
        //slotProduction.lastSlot = slotProduction.lastSlot;
        slotProduction.lastTimeStamp = block.timestamp;
        // console.log (">>>>>> Chain updated");   

        // this statement controls whether Confirmed Index slot Head moved from zero
        // moved from zero
        }
    }

}

contracts/DrexMerkle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24; 

    import {ReentrancyGuard} from "./utils/ReentrancyGuard.sol";
    import {ListrackMerkle} from "./ListrackMerkle.sol";

    // import "./utils/console.sol";

    import "./utils/math.sol";

    import "hardhat/console.sol";

    interface I_Listrack {
    function sendTxForSettlement (bytes32[] memory) external;
    function revertTxsbyMerkleContract (address _merkleContract) external;
    }

    contract MerkleContract is ReentrancyGuard  {

   // using SignatureChecker for bytes32;

    // Event to emit when a new Merkle root consensus is achieved
    event AlienMerkleConsensus   (uint256 indexed blockNumber, 
                                bytes32 indexed alienRootHash);

    // Event to emit when a new set of Approvers is requested
    event PendingNewApprovers   (address[] indexed approvers, uint256[] indexed weights,
                                bytes32 indexed hash);

    event NewApprovers (bytes32 indexed hash);

    struct listApprovers {
        address pKey;
        uint256 weight;
    }

/*
    struct MempoolTX {
        bytes32 txId;
        bool    paid;
        bool    alienConfirmed;
    }
    */

    struct TxMerkleDetails {
        bool    paid;
        bool    alienConfirmed;
    }


    // historic list of approvers 
   // mapping (uint256 => address[]) public approvers;

   // mapping that stores the merkle trees
   // blockNumber => Merkle Tree
    mapping (uint256 => bytes32) merkleHashesbyBlock;

    // list of verified tx inserted by any user whose root is equal to a 
    // merkle root already voted;
    mapping (uint256 => bytes32[]) verifiedTxbyBlock;

    // current approvers
    listApprovers[] public currentApprovers;

    // list of pendingApprovers by their committed hash
    mapping (bytes32 => listApprovers[]) public pendingApprovers;

    // current weight of currentApprovers;
    uint256 currentWeight;

    // pending weight of pendingApprovers;
    uint256 pendingWeight;

    // current approvers Map that links address to weight
     mapping (address => uint256) public approversWeightMap;

    // pending Approvers Hash that must be signed by current approvers
    bytes32 public pendingApproversHash;

    // number of votes for each MerkleRoot
    // block number => merkle root => number of votes
    mapping (uint256=>mapping(bytes32=>uint256)) pollList;

    // hash of new voters => number of votes
    mapping (bytes32=>uint256) pollListNewApprovers;

    // mapping of Merkle Hashes to approvers that voted or not
    // blockNumber => Merkle Hash => approver Address => true or false
    mapping (uint256=>mapping(bytes32=>mapping(address=>bool))) alreadyVoted;

    // mapping of Merkle Hashes to approvers that are willing to change the Approvers set
    mapping (bytes32=>mapping(address=>bool)) alreadyVotedNewApprovers;

    // currentRatioApproval is the minimum quorum for approving the Alien Merkle Root
    uint256 currentRatioApproval;

    // value of the service provided by DrexMerkle Contract in native tokens
    uint256 valueServiceProvided;

    // transactions sent to mempool to confirm in AlienListrack
    bytes32 [] mempoolTx;

    // mapping that stores the details of each Merkle Transaction
    mapping (bytes32 => TxMerkleDetails) txMerkleDetails;
    
    // Modifier to restrict access to owner
    modifier onlyOwner() {
        bool _existApprover = false;
        for (uint i=0 ; i < currentApprovers.length ; i++) {
            if ((currentApprovers[i].pKey == msg.sender) && (currentApprovers[i].weight!=0))
            _existApprover = true;
        }
        require(_existApprover,
            "Unauthorized: Only owner can perform this action"
        );
        _;
    }

    constructor (address[] memory _approvers, uint256[] memory _weights, uint256 _valueServiceProvided) {
     require (_approvers.length == _weights.length, 
        "Array of approvers is no/t equal to weights");

    valueServiceProvided = _valueServiceProvided;

    currentWeight = 0;
    
    listApprovers memory eachApprover;

    for (uint i=0 ; i<_approvers.length; i++) {
    eachApprover.pKey = _approvers[i];
    eachApprover.weight = _weights[i];
    currentApprovers.push(eachApprover);

    approversWeightMap[_approvers[i]] = _weights[i];
    currentWeight += _weights[i];
    }
    currentRatioApproval = 7000; // at least 70% of approvers must confirm Merkle Root
    console.log ("@@@ Merkle Contract Deployed - Current Weight ",currentWeight);
    //console.log ("Approver 0 ",currentApprovers[0].pKey);
    //console.log ("Approver 1 ",currentApprovers[1].pKey);
    //console.log ("Approver 2 ",currentApprovers[2].pKey);
    //console.log ("Approver 3 ",currentApprovers[3].pKey);
    }


    function requireNewApprovers (address[] memory _approvers, uint256[] memory _weights) 
    external onlyOwner {

        uint256 _sizeApprovers = _approvers.length;

        require (_sizeApprovers == _weights.length, "Address and Weight are not the same size");
        listApprovers[] memory _pendingApprovers = new listApprovers[](_sizeApprovers);

        // console.log ("Size Approvers", _sizeApprovers);

        bytes32 _hash = bytes32(0);

        for (uint i=0 ; i<_approvers.length; i++) {
        _pendingApprovers[i].pKey = _approvers[i];
       //  console.log ("Pending Approvers Key",  _pendingApprovers[i].pKey );
        _pendingApprovers[i].weight = _weights[i];
        _hash = keccak256(abi.encodePacked(_hash,_approvers[i],_weights[i]));
        }

        //console.log("Hash of the Approvers");
        //console.logBytes32( _hash);

        emit PendingNewApprovers (_approvers,_weights,_hash);
        for (uint j=0; j<_sizeApprovers ; j++) {
        listApprovers memory _approver = _pendingApprovers[j];
        pendingApprovers[_hash].push(_approver);
        }
    }

     function agreeNewApprovers (bytes32 _hash) external onlyOwner nonReentrant {
        //console.log ("Already voted for new approvers ? ", 
        //alreadyVotedNewApprovers[_hash][msg.sender]);

        require (!alreadyVotedNewApprovers[_hash][msg.sender],
                "Approver already voted");

        alreadyVotedNewApprovers[_hash][msg.sender] = true;
        pollListNewApprovers[_hash] += approversWeightMap[msg.sender];
        
        if ((pollListNewApprovers[_hash]*10000) >= (currentRatioApproval*currentWeight))
         {
            //console.log ("Consensus achieved");
          //console.log ("Current Ratio : ", (pollListNewApprovers[_hash]*_multiplier));
          

          // ATTENTION !!! 
          /// ATTENTION !!! CONVERT TO UNCOMMENTED AFTER DEVELOPMENT IN HARDHAT
          // The below statement warrants payments to all current approvers before changing the set
          // splitMerkleValueService ();


          // the below statement converts the map pendingApprovers to Current Approvers
          for (uint i=0 ; i < currentApprovers.length; i++) {
            approversWeightMap [currentApprovers[i].pKey] = 0; // removed approvers lose their weight
          }
          currentApprovers = pendingApprovers[_hash];  
          uint256 _cumulativeWeight = 0;
          for (uint i=0 ; i < currentApprovers.length; i++) {
            approversWeightMap [currentApprovers[i].pKey] = currentApprovers[i].weight;
            _cumulativeWeight += currentApprovers[i].weight;
          }
          currentWeight = _cumulativeWeight;
          emit NewApprovers (_hash);
        }
    }

    function insertMerkleForApproval (bytes32 _pendingMerkle, uint256 _alienBlock) 
                                        public onlyOwner nonReentrant {
        
        //console.log ("Already Voted for the Merkle Hash? ", alreadyVoted[_alienBlock][_pendingMerkle][msg.sender]);
        
        require (!alreadyVoted[_alienBlock][_pendingMerkle][msg.sender],
                "Approver already voted");

        require (merkleHashesbyBlock[_alienBlock] == bytes32(0),
        "Merkle Hash for this block is already written");

        alreadyVoted[_alienBlock][_pendingMerkle][msg.sender] = true;
        pollList[_alienBlock][_pendingMerkle] += approversWeightMap[msg.sender];

        //console.log ("Current vote for block: ", _alienBlock);
        //console.log ("Current weighted vote without multiplier: ", pollList[_alienBlock][_pendingMerkle]);
        //console.log ("Current Weight ",currentWeight);
        //console.log ("Multiplier ", _multiplier);
        //console.log ("Current Weighted Vote ",pollList[_alienBlock][_pendingMerkle]*_multiplier);

        
        if ((pollList[_alienBlock][_pendingMerkle]*10000) >= (currentRatioApproval*currentWeight)) {
          merkleHashesbyBlock[_alienBlock] = _pendingMerkle;  
          console.log ("Consensus achieved for Merkle Root");
          //console.log ("Current Weighted Vote : ", (pollList[_pendingMerkle][_alienBlock]*_multiplier));
          emit AlienMerkleConsensus (_alienBlock, _pendingMerkle);
        }
    }

     function getRootByBlock (uint256 _blockNumber) external view returns (bytes4, bytes32) {
        bytes4   _success = bytes4(0);
        bytes4   _magicNumber = 0x1626ba7e;
        bytes32 _returnedValue = bytes32(0);

        _returnedValue = merkleHashesbyBlock[_blockNumber];
        if (_returnedValue!=bytes32(0)) _success = _magicNumber;
        return (_success,_returnedValue);
     }

    // the below function does not require Merkle Proof because all transactions are listed
    // Drex Listrack only settles the transactions that this Merkle Contract is responsible
    // Drex Listrack does not settle transactions that the current Merkle Contract is not in charge
     function validateAllTxForSettlementForOneAlienBlock (uint256 _alienBlock,
                                        bytes32[] memory _transactions,
                                        address _drexListrack) external onlyOwner nonReentrant {
        require (verifiedTxbyBlock[_alienBlock].length==0,
        "Transactions already validated for this alien block");
        bytes32 _hash = genMerkleTree (_transactions);
        if (_hash == merkleHashesbyBlock[_alienBlock]) {
            verifiedTxbyBlock[_alienBlock] = _transactions;
            I_Listrack(_drexListrack).sendTxForSettlement(_transactions);
        }
    }

     function validateSomeTxForSettlement (bytes32[] memory _txId, uint256[] memory _txIndex,
                                        uint256[] memory _leafCount,
                                        bytes32[][] memory _merkleProof, uint256[] memory _alienBlock, 
                                        address _drexListrack) external onlyOwner nonReentrant {
        //require (verifiedTxbyBlock[_alienBlock].length==0,
        //"Transactions already validated for this alien block");
       // bytes32[] memory _txSend = new bytes32[](1);
        uint256 _successCounter = 0;
        bool _merkleValidated;

       for (uint256 i = 0 ; i < _txId.length ; i++) {
        _merkleValidated = false;
        if (txMerkleDetails[_txId[i]].alienConfirmed) {
            _merkleValidated = true;
            } else {
            _merkleValidated = validateMerkleProof(_txId[i], _txIndex[i], _leafCount[i], _merkleProof[i], _alienBlock[i]);
            if (_merkleValidated) txMerkleDetails[_txId[i]].alienConfirmed = true;                   
            }
            // ATTENTION
            // ATTENTION
            // ATTENTION
            // CHANGE TO BELOW STATEMENT AFTER HARDHAT PRELIMINARY TESTS
       // if ((_merkleValidated) && (txMerkleDetails[_txId[i]].paid)) _successCounter++;
            if (_merkleValidated) _successCounter++;
       }
       if (_successCounter == _txId.length) {
        I_Listrack(_drexListrack).sendTxForSettlement(_txId);
       }
        }

/* FOR DEV PURPOSES ONE TX FOR SETTLEMENT FOR TESTS
    function validateOneTxForSettlement (bytes32 _txId, uint256 _txIndex, 
                                        bytes32[] memory _merkleProof, uint256 _alienBlock, 
                                        address _drexListrack) external onlyOwner {
        require (verifiedTxbyBlock[_alienBlock].length==0,
        "Transactions already validated for this alien block");
        bytes32[] memory _txSend = new bytes32[](1);
        _txSend[0] = _txId;
        if (validateMerkleProof(_txId, _txIndex, _merkleProof, _alienBlock)) {
            I_Listrack(_drexListrack).sendTxForSettlement(_txSend); }
        }

        */

    // committed root of a full list of TxIds (same scheme as AlienListrack, see ListrackMerkle)
    function genMerkleTree(bytes32[] memory _transactions) public pure returns (bytes32) {
        return ListrackMerkle.committedRoot(_transactions);
    }

    function validateMerkleProof (bytes32 _txId, uint256 _txIndex, uint256 _leafCount,
    bytes32[] memory _merkleProof, uint256 _alienBlock) private view returns (bool) {
        (bool _ok, bytes32 _root) = ListrackMerkle.computeRoot(_txId, _txIndex, _leafCount, _merkleProof);
        return _ok && merkleHashesbyBlock[_alienBlock] != bytes32(0) && merkleHashesbyBlock[_alienBlock] == _root;
    }

    // function to revert txs in Listrack automatically
    // gas fees are charged in the current contract
    function revertTxs (address _drexListrack) external nonReentrant {
        I_Listrack(_drexListrack).revertTxsbyMerkleContract(address(this));
    }

    function payTxToMerkleContract (bytes32 _TxId) external 
    payable returns (bool) {
        bool  _success = false;

        require (msg.value == valueServiceProvided, 
        "Value is not the exact value for the Service to confirm Tx by Merkle Contract");

         _success = true; // msg.value is already held by this contract

        if (_success) {
            mempoolTx.push(_TxId);
            txMerkleDetails[_TxId].paid = true;
            txMerkleDetails[_TxId].alienConfirmed = false;
        }
        return (_success);
        }

    function splitMerkleValueService () public payable onlyOwner {
        uint256 _multiplier = address(this).balance/currentWeight;
        uint256 _valueforEach = 0;
        bool    _success;
        
        for (uint256 i=0 ; i<currentApprovers.length ; i++) {
            _valueforEach = _multiplier * currentApprovers[i].weight; 
            (_success,) = payable(currentApprovers[i].pKey).call{value:_valueforEach}("");
            _valueforEach = 0;
        }
        
        }

    function getVerifiedTxbyBlock (uint256 _alienBlock) public view returns (bool,bytes32[] memory) {
        bool _success = false;
        bytes32[] memory _TxIdArray = verifiedTxbyBlock[_alienBlock];
        if (_TxIdArray.length!=0) _success = true;
        return (_success,_TxIdArray);
    }
        
        
     }

contracts/ListrackMerkle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title ListrackMerkle
/// @notice Single source of truth for the Merkle scheme shared by AlienListrack,
///         DrexListrack (MainListrack) and MerkleContract (MainMerkle).
///
/// Scheme (Section 4.3 of the paper):
///   leaf      = keccak256(0x00 || TxId)
///   node      = keccak256(0x01 || left || right)
///   odd level = the last node is paired with itself
///   committed = keccak256(0x02 || leafCount || treeRoot)
///
/// Domain separation stops an internal node from being presented as a leaf.
/// Binding the leaf count into the committed root fixes the tree shape, so the
/// verifier can require the exact proof length and a leaf index below the count.
/// This removes the duplicated-last-node ambiguity (the pattern behind
/// CVE-2012-2459 in Bitcoin).
library ListrackMerkle {

    function leafHash(bytes32 txId) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(bytes1(0x00), txId));
    }

    function nodeHash(bytes32 left, bytes32 right) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(bytes1(0x01), left, right));
    }

    function commit(uint256 leafCount, bytes32 treeRoot) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(bytes1(0x02), leafCount, treeRoot));
    }

    /// @notice Number of sibling hashes in a proof for a tree of `leafCount` leaves.
    function depth(uint256 leafCount) internal pure returns (uint256 d) {
        uint256 size = leafCount;
        while (size > 1) {
            size = (size + 1) / 2;
            d++;
        }
    }

    /// @notice Committed root of a list of transaction identifiers.
    function committedRoot(bytes32[] memory txIds) internal pure returns (bytes32) {
        uint256 n = txIds.length;
        require(n > 0, "No data to create Merkle tree");
        bytes32[] memory level = new bytes32[](n);
        for (uint256 i = 0; i < n; i++) level[i] = leafHash(txIds[i]);
        while (level.length > 1) {
            uint256 m = (level.length + 1) / 2;
            bytes32[] memory next = new bytes32[](m);
            for (uint256 i = 0; i < level.length; i += 2) {
                bytes32 right = (i + 1 < level.length) ? level[i + 1] : level[i];
                next[i / 2] = nodeHash(level[i], right);
            }
            level = next;
        }
        return commit(n, level[0]);
    }

    /// @notice Sibling path for the leaf at `index`. For the last node of an odd
    ///         level the sibling is the node itself.
    function proof(bytes32[] memory txIds, uint256 index) internal pure returns (bytes32[] memory path) {
        uint256 n = txIds.length;
        require(index < n, "Leaf index out of range");
        path = new bytes32[](depth(n));
        bytes32[] memory level = new bytes32[](n);
        for (uint256 i = 0; i < n; i++) level[i] = leafHash(txIds[i]);
        uint256 k = 0;
        while (level.length > 1) {
            uint256 sib = (index % 2 == 0) ? index + 1 : index - 1;
            path[k++] = (sib < level.length) ? level[sib] : level[index];
            uint256 m = (level.length + 1) / 2;
            bytes32[] memory next = new bytes32[](m);
            for (uint256 i = 0; i < level.length; i += 2) {
                bytes32 right = (i + 1 < level.length) ? level[i + 1] : level[i];
                next[i / 2] = nodeHash(level[i], right);
            }
            level = next;
            index /= 2;
        }
    }

    /// @notice Recomputes the committed root from a leaf and its proof.
    /// @return ok   false if the proof is malformed for this leaf count
    /// @return root the committed root (meaningful only when ok is true)
    function computeRoot(bytes32 txId, uint256 index, uint256 leafCount, bytes32[] memory path)
        internal pure returns (bool ok, bytes32 root)
    {
        if (leafCount == 0 || index >= leafCount) return (false, bytes32(0));
        if (path.length != depth(leafCount)) return (false, bytes32(0));
        bytes32 h = leafHash(txId);
        uint256 size = leafCount;
        for (uint256 k = 0; k < path.length; k++) {
            if (index % 2 == 0) {
                if (index + 1 == size) {
                    // last node of an odd level: must be paired with itself
                    if (path[k] != h) return (false, bytes32(0));
                }
                h = nodeHash(h, path[k]);
            } else {
                h = nodeHash(path[k], h);
            }
            index /= 2;
            size = (size + 1) / 2;
        }
        return (true, commit(leafCount, h));
    }
}

